using System.Collections.Concurrent;using EnterpriseDocumentIntelligence.AuditService.Application;using EnterpriseDocumentIntelligence.AuditService.Domain; namespace EnterpriseDocumentIntelligence.AuditService.Infrastructure; public sealed class InMemoryAuditStore:IAuditStore{private readonly ConcurrentDictionary<Guid,AuditRecord> _items=new();public Task<bool> ExistsAsync(Guid id,CancellationToken ct=default)=>Task.FromResult(_items.ContainsKey(id));public Task AppendAsync(AuditRecord r,CancellationToken ct=default){_items.TryAdd(r.EventId,r);return Task.CompletedTask;}public Task<IReadOnlyList<AuditRecord>> QueryAsync(string tenantId,string? resourceId=null,CancellationToken ct=default)=>Task.FromResult((IReadOnlyList<AuditRecord>)_items.Values.Where(x=>x.TenantId==tenantId&&(resourceId==null||x.ResourceId==resourceId)).OrderByDescending(x=>x.OccurredAt).ToList());} public static class AuditServiceInfrastructure{public static IServiceCollection AddAuditApplication(this IServiceCollection services){services.AddSingleton<IAuditStore,InMemoryAuditStore>();services.AddScoped<AuditApplication>();return services;}}